@st.cache_resource
def load_artifacts():
    preprocessor = joblib.load("preprocessor.pkl")
    model        = joblib.load("gbr_model.pkl")
    return preprocessor, model

try:
    preprocessor, model = load_artifacts()
    model_loaded = True
except FileNotFoundError:
    model_loaded = False

